/* Offline worker (docs/specs/hsk-app.spec.html #offline): saves every published file into one
   cache per version, answers listed files from it, and swaps in a new copy only once complete.
   It never reloads a page; the next open shows the new version. */

const PREFIX = "hsk-";
const CACHE = PREFIX + VERSION;
const ROOT = new URL("./", self.location).href;
const LISTED = new Set(FILES.map((f) => ROOT + f));

// A complete save or nothing: addAll stores no file unless every one arrived. Files come
// past the browser's HTTP cache so a new version never saves an older copy.
self.addEventListener("install", (e) => {
  e.waitUntil(
    caches.open(CACHE)
      .then((c) => c.addAll(FILES.map((f) => new Request(ROOT + f, { cache: "reload" }))))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener("activate", (e) => {
  e.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith(PREFIX) && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener("fetch", (e) => {
  const req = e.request;
  if (req.method !== "GET" || !req.url.startsWith(ROOT)) return;
  const url = new URL(req.url);
  url.hash = "";
  url.search = "";
  const key = url.href.endsWith("/") ? url.href + "index.html" : url.href;
  if (LISTED.has(key)) {
    e.respondWith(caches.open(CACHE).then((c) => c.match(key)).then((hit) => (hit ? ranged(req, hit) : fetch(req))));
  } else if (req.mode === "navigate") {
    // An unknown page address offline shows the network.
    e.respondWith(fetch(req).catch(() => caches.open(CACHE).then((c) => c.match(ROOT + "index.html")).then((hit) => hit || Response.error())));
  }
});

// Safari asks for recordings by byte range and plays only a 206 answer.
async function ranged(req, res) {
  const m = /^bytes=(\d*)-(\d*)$/.exec(req.headers.get("range") || "");
  if (!m || (m[1] === "" && m[2] === "")) return res;
  const body = await res.arrayBuffer();
  const size = body.byteLength;
  const start = m[1] === "" ? Math.max(0, size - Number(m[2])) : Number(m[1]);
  const end = m[1] === "" || m[2] === "" ? size - 1 : Math.min(Number(m[2]), size - 1);
  if (start > end) return new Response(null, { status: 416, headers: { "Content-Range": `bytes */${size}` } });
  return new Response(body.slice(start, end + 1), {
    status: 206,
    headers: {
      "Content-Type": res.headers.get("Content-Type") || "",
      "Content-Length": String(end - start + 1),
      "Content-Range": `bytes ${start}-${end}/${size}`,
    },
  });
}
